import math
from itertools import permutations

def get_divisors(m):
    divs = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)
    return sorted(list(divs))

def sum_of_divisors(m):
    return sum(get_divisors(m))

def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

def solve_permutation_problem(m, divisors):
    sigma_m = sum_of_divisors(m)
    if not is_perfect_square(sigma_m):
        return "N/A (Sigma not square)"

    # DFS search for a valid permutation
    n = len(divisors)

    # State: (current_sum, used_mask)
    # We are looking for a path of length n where all partial sums are squares.

    # We use a recursive backtracking approach.

    def find_sequence(current_sum, remaining_divisors_set, sequence_length):
        if sequence_length == n:
            # We reached the end. The final sum must be sigma_m, which we already know is a square.
            return True

        for d in remaining_divisors_set:
            new_sum = current_sum + d
            if is_perfect_square(new_sum):
                new_remaining = remaining_divisors_set - {d}
                if find_sequence(new_sum, new_remaining, sequence_length + 1):
                    return True
        return False

    # Start with sum 0, all divisors remaining, length 0.
    if find_sequence(0, set(divisors), 0):
        return "Success"
    else:
        return "Failure"

# --- Main loop ---
results = {}
for m in range(2, 101):
    divisors = get_divisors(m)
    sigma = sum_of_divisors(m)

    if is_perfect_square(sigma):
        status = solve_permutation_problem(m, divisors)
        results[m] = status
    else:
        # If sigma is not a square, the condition cannot be met for i=n.
        results[m] = "Impossible (Sigma not square)"

# Format results for logging
output = []
for m in sorted(results.keys()):
    status = results[m]
    output.append(f"m={m}: Divisors={get_divisors(m)}, Sigma={sum_of_divisors(m)} ({'Square' if is_perfect_square(sum_of_divisors(m)) else 'Not Square'}). Result: {status}")

print("\\n".join(output))

