def sigma(n):
    """Calculates the sum of divisors function sigma(n)."""
    sum_div = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            sum_div += i
            if i*i != n:
                sum_div += n // i
    return sum_div

def is_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    sqrt_n = int(n**0.5)
    return sqrt_n * sqrt_n == n

candidates = []
for m in range(101, 201):
    s = sigma(m)
    if is_square(s):
        candidates.append(m)

